    box: [['Испанский', 'El Corazón del mundo'], ['Роман', '[[zvezdnyj-roman|Звёздный роман]], гл. 13–17'], ['Облик', 'золотое ядро, парящее над полом'], ['Страж', 'Страж Света — то ли птица, то ли скат'], ['Место', 'зал под маяком; затем вражеский корабль и [[atlantida|Атлантида]]'], ['Последняя искра', 'спрятана в [[luciano|Лусиано]]']],
